package dev.halloween;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.minecraft.block.*;
import net.minecraft.util.math.*;
import net.minecraft.world.GameMode;
/** Physical boarding and connected stairs: ordinary client inputs, no waypoint teleports. */
final class NavalAccessChecks {
 static final int KIND=Integer.getInteger("halloween.navalAccessKind",2);
 static volatile boolean prepared;static volatile int id;static RailVehicleEntity ship;static volatile RailVehicleEntity serverShip;static int phase,age,wait;static Vec3d sailStart;static float sailYaw;static final double[][] ROUTE={{5.2,-5.4,2.5},{3.8,-5.4,3},{3.8,-10.9,6},{0,-9.2,6},{3.8,-10.9,6},{3.8,-5.4,3},{3.8,-6.1,3},{0,-6.1,3},{0,2.2,.95}};
 static void require(boolean value,String why){if(!value)throw new AssertionError(why);}
 static void register(){if(!Boolean.getBoolean("halloween.navalAccessTest"))return;
  ServerTickEvents.END_SERVER_TICK.register(server->{if(prepared)return;var w=server.getOverworld();if(w.getPlayers().isEmpty())return;var p=w.getPlayers().getFirst();var origin=new Vec3d(-1048.5,63,1088.5);var cp=new ChunkPos(BlockPos.ofFloored(origin));for(int x=-3;x<=3;x++)for(int z=-3;z<=3;z++)w.setChunkForced(cp.x+x,cp.z+z,true);if(++wait<80)return;
   for(var old:RailVehicleEntity.nearby(w,new Box(origin,origin).expand(150)))old.discard();var vessel=NavalContent.spawn(w,KIND,origin,0);require(vessel!=null,"brig fits ocean");serverShip=vessel;vessel.naval().cargo.setStack(0,new net.minecraft.item.ItemStack(net.minecraft.item.Items.DIAMOND,7));id=vessel.getId();
   for(int x=8;x<=12;x++)for(int z=-7;z<=-4;z++)w.setBlockState(BlockPos.ofFloored(origin.add(x*NavalGeometry.sx(KIND),0,z*NavalGeometry.sz(KIND))),Blocks.OAK_SLAB.getDefaultState(),Block.NOTIFY_LISTENERS);
   // Half-height pier touches the lowest boarding tread, without replacing any ocean water below it.
   p.stopRiding();p.changeGameMode(GameMode.SURVIVAL);p.setHealth(20);p.getAbilities().flying=false;p.sendAbilitiesUpdate();p.networkHandler.requestTeleport(origin.x+9*NavalGeometry.sx(KIND),origin.y+.5,origin.z-5.4*NavalGeometry.sz(KIND),90,0);prepared=true;
  });
  ClientTickEvents.START_CLIENT_TICK.register(c->{if(!prepared||phase<0||c.player==null||c.world==null)return;if(ship==null)ship=c.world.getEntityById(id) instanceof RailVehicleEntity t?t:null;if(ship==null)return;c.options.pauseOnLostFocus=false;if(c.currentScreen instanceof net.minecraft.client.gui.screen.GameMenuScreen)c.setScreen(null);
   try{age++;
    if(phase==ROUTE.length){c.options.forwardKey.setPressed(false);if(c.currentScreen instanceof net.minecraft.client.gui.screen.ingame.GenericContainerScreen){require(c.player.currentScreenHandler.getSlot(0).getStack().isOf(net.minecraft.item.Items.DIAMOND)&&c.player.currentScreenHandler.getSlot(0).getStack().getCount()==7,"actual server cargo contents reached the client screen");c.player.closeHandledScreen();c.getServer().execute(()->{var p=c.getServer().getOverworld().getPlayers().getFirst();var target=RailGeometry.rotate(NavalGeometry.local(KIND,0,6,-9.2),serverShip.getYaw()).add(serverShip.getEntityPos());p.networkHandler.requestTeleport(target.x,target.y,target.z,180,20);});phase++;age=0;org.slf4j.LoggerFactory.getLogger("naval-access-test").info("PASS real cargo container opens with exact server inventory");}require(age<100,"cargo screen did not open");return;}
    if(phase==ROUTE.length+1){c.options.forwardKey.setPressed(false);if(age<35)return;var target=RailGeometry.rotate(NavalGeometry.local(KIND,0,6.98,-10.72),ship.getYaw()).add(ship.getEntityPos());var diff=target.subtract(c.player.getEyePos());c.player.setYaw((float)Math.toDegrees(Math.atan2(-diff.x,diff.z)));c.player.setPitch((float)-Math.toDegrees(Math.atan2(diff.y,diff.horizontalLength())));var hit=c.player.getCrosshairTarget(1,c.player);require(hit instanceof net.minecraft.util.hit.EntityHitResult entity&&entity.getEntity()==ship,"wheel visible geometry is clickable through actual crosshair: "+hit);c.interactionManager.interactEntity(c.player,ship,net.minecraft.util.Hand.MAIN_HAND);phase++;age=0;return;}
    if(phase==ROUTE.length+2){if(age<25)return;if(c.player.getVehicle()==null){require(age<100,"helm mount packet did not arrive");return;}require(c.player.getVehicle() instanceof RailSeatEntity seat&&seat.controls()&&seat.train()==ship,"right-click wheel really sits player at helm");require(Math.abs(RailPassengerNetwork.toLocal(ship,c.player.getEntityPos()).y-5.665)<.12,"helmsman pelvis rests on chair cushion");org.slf4j.LoggerFactory.getLogger("naval-access-test").info("PASS actual crosshair targeting, helm seat and quarterdeck foot position");sailStart=ship.getEntityPos();sailYaw=ship.getYaw();c.options.forwardKey.setPressed(true);c.options.jumpKey.setPressed(true);phase++;age=0;return;}
    if(phase==ROUTE.length+3){c.options.jumpKey.setPressed(false);c.options.forwardKey.setPressed(true);c.options.rightKey.setPressed(age>120);if(age<280)return;require(ship.getEntityPos().distanceTo(sailStart)>8,"real client helm packets make vessel sail");require(Math.abs(MathHelper.wrapDegrees(ship.getYaw()-sailYaw))>10,"real client rudder packets steer ship: yaw="+ship.getYaw()+" initial="+sailYaw);c.options.forwardKey.setPressed(false);c.options.rightKey.setPressed(false);c.options.jumpKey.setPressed(true);phase++;age=0;return;}
    if(phase==ROUTE.length+4){c.options.jumpKey.setPressed(false);if(age<100)return;require(ship.anchored()&&Math.abs(ship.getVelocity().horizontalLength())<.01,"client anchor packet stops vessel");phase=-1;org.slf4j.LoggerFactory.getLogger("naval-access-test").info("PASS actual client helm thrust/rudder/anchor packets: vessel accelerates, turns and stops safely");c.scheduleStop();return;}

    if(age<30)return;double[] point=ROUTE[Math.min(phase,ROUTE.length-1)];var local=RailPassengerNetwork.toLocal(ship,c.player.getEntityPos());var target=RailGeometry.rotate(NavalGeometry.local(KIND,point[0],local.y,point[1]),ship.getYaw()).add(ship.getEntityPos());var diff=target.subtract(c.player.getEntityPos());c.player.setYaw((float)Math.toDegrees(Math.atan2(-diff.x,diff.z)));c.player.setPitch(0);c.options.forwardKey.setPressed(diff.horizontalLength()>.2);c.options.jumpKey.setPressed(false);c.options.sneakKey.setPressed(false);
    if(diff.horizontalLength()<.22){c.options.forwardKey.setPressed(false);if(phase==0&&local.y>=1.5||Math.abs(local.y-point[2])<.18){org.slf4j.LoggerFactory.getLogger("naval-access-test").info("PASS waypoint {} actual={}",phase,local);if(++phase==ROUTE.length){org.slf4j.LoggerFactory.getLogger("naval-access-test").info("PASS real walking from pier up boarding stairs, main deck, side stairs, helm quarterdeck, return stairs and cargo hold");c.interactionManager.interactEntity(c.player,ship,net.minecraft.util.Hand.MAIN_HAND);}age=30;}}
    require(c.player.isAlive()&&c.player.getHealth()>19,"boarder unharmed");require(age<280,"path blocked phase="+phase+" actual="+local+" target="+java.util.Arrays.toString(point));
   }catch(Throwable e){c.options.forwardKey.setPressed(false);phase=-1;org.slf4j.LoggerFactory.getLogger("naval-access-test").error("FAIL",e);c.scheduleStop();}
  });
 }
}
